{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "GSK1322322, an aminopyrimidine with a methoxy-substituted aniline and basic amine, achieved 77% absolute oral bioavailability in healthy volunteers after a meal, supporting high F for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The same GSK1322322 tablet gave 57% absolute oral bioavailability in the fasted state, showing high F is maintained across prandial conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Zongertinib, an acrylamide-containing kinase inhibitor with an aminoheteroaryl core, was predicted to have 41% human oral bioavailability, supporting high F for the query's acrylamide/aminopyrimidine design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "CC-292, an acrylamide aminopyrimidine BTK inhibitor, showed excellent oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Deucravacitinib, a heteroaromatic kinase inhibitor, had 99% absolute oral bioavailability in healthy subjects, supporting high F for this compound class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite unfavorable physicochemical priors, the closest experimental analogues—acrylamide/aminopyrimidine kinase inhibitors with similar polar and basic functionality—show human oral bioavailability well above 20% (41–99%). Therefore predict high F.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "Isopropyl ester hydrolysis and solubility of this specific compound are not experimentally characterized.",
    "Human pharmacokinetic data after oral dosing would be needed to confirm the prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

